template:
struct Order {
    id: u32,
    count: u32,
    express: bool,
}

fn bump(base: Order) -> Order {
    Order { count: ⟦bumped⟧, ⟦rest⟧ }
}

fn main() {
    let next = bump(Order { id: 7, count: 2, express: true });
    println!("{}", next.count);
}

tests:
#[test]
fn bumps() {
    let next = bump(Order { id: 7, count: 2, express: true });
    assert_eq!(next.count, 3);
    assert_eq!(next.id, 7);
    assert!(next.express);
}
